BEGIN TRANSACTION;
CREATE TABLE carrier_calendars (
	id VARCHAR NOT NULL, 
	carrier_id VARCHAR NOT NULL, 
	day_of_week INTEGER NOT NULL, 
	start_time VARCHAR(5) NOT NULL, 
	end_time VARCHAR(5) NOT NULL, 
	is_operational BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (day_of_week BETWEEN 0 AND 6), 
	FOREIGN KEY(carrier_id) REFERENCES carriers (id)
);
CREATE TABLE carriers (
	id VARCHAR NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	carrier_type VARCHAR(30) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE delay_reasons (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR NOT NULL, 
	eta_estimate_id VARCHAR, 
	reason_code VARCHAR(50) NOT NULL, 
	description TEXT NOT NULL, 
	impact_minutes FLOAT NOT NULL, 
	detected_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(eta_estimate_id) REFERENCES eta_estimates (id)
);
CREATE TABLE disruption_windows (
	id VARCHAR NOT NULL, 
	disruption_type VARCHAR(50) NOT NULL, 
	facility_id VARCHAR, 
	route_id VARCHAR, 
	weather_event_id VARCHAR, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	impact_minutes FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (end_time > start_time), 
	CHECK (impact_minutes >= 0), 
	FOREIGN KEY(facility_id) REFERENCES facilities (id), 
	FOREIGN KEY(route_id) REFERENCES routes (id), 
	FOREIGN KEY(weather_event_id) REFERENCES weather_events (id)
);
CREATE TABLE eta_estimates (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR NOT NULL, 
	prediction_time DATETIME NOT NULL, 
	feature_cutoff_time DATETIME NOT NULL, 
	predicted_arrival_at DATETIME NOT NULL, 
	delay_probability FLOAT NOT NULL, 
	predicted_delay_minutes FLOAT NOT NULL, 
	model_version VARCHAR(50) NOT NULL, 
	prediction_status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (shipment_id, prediction_time, model_version), 
	CHECK (delay_probability >= 0 AND delay_probability <= 1), 
	CHECK (predicted_delay_minutes >= 0), 
	CHECK (feature_cutoff_time <= prediction_time), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id)
);
CREATE TABLE facilities (
	id VARCHAR NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	facility_type VARCHAR(30) NOT NULL, 
	city VARCHAR(80) NOT NULL, 
	state VARCHAR(80), 
	country VARCHAR(80), 
	latitude FLOAT, 
	longitude FLOAT, 
	capacity INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (capacity > 0)
);
CREATE TABLE facility_calendars (
	id VARCHAR NOT NULL, 
	facility_id VARCHAR NOT NULL, 
	day_of_week INTEGER NOT NULL, 
	start_time VARCHAR(5) NOT NULL, 
	end_time VARCHAR(5) NOT NULL, 
	is_operational BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (day_of_week BETWEEN 0 AND 6), 
	FOREIGN KEY(facility_id) REFERENCES facilities (id)
);
CREATE TABLE facility_queues (
	id VARCHAR NOT NULL, 
	facility_id VARCHAR NOT NULL, 
	observed_at DATETIME NOT NULL, 
	queue_length INTEGER NOT NULL, 
	capacity INTEGER NOT NULL, 
	average_wait_minutes FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (queue_length >= 0), 
	CHECK (capacity > 0), 
	CHECK (average_wait_minutes >= 0), 
	FOREIGN KEY(facility_id) REFERENCES facilities (id)
);
CREATE TABLE route_weather (
	route_id VARCHAR NOT NULL, 
	weather_event_id VARCHAR NOT NULL, 
	impact_factor FLOAT NOT NULL, 
	PRIMARY KEY (route_id, weather_event_id), 
	FOREIGN KEY(route_id) REFERENCES routes (id), 
	FOREIGN KEY(weather_event_id) REFERENCES weather_events (id)
);
CREATE TABLE routes (
	id VARCHAR NOT NULL, 
	route_name VARCHAR(150) NOT NULL, 
	origin_facility_id VARCHAR NOT NULL, 
	destination_facility_id VARCHAR NOT NULL, 
	distance_km FLOAT NOT NULL, 
	estimated_duration_minutes INTEGER NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (distance_km > 0), 
	CHECK (estimated_duration_minutes > 0), 
	FOREIGN KEY(origin_facility_id) REFERENCES facilities (id), 
	FOREIGN KEY(destination_facility_id) REFERENCES facilities (id)
);
CREATE TABLE service_levels (
	id VARCHAR NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	code VARCHAR(30) NOT NULL, 
	target_transit_hours FLOAT NOT NULL, 
	allowed_delay_minutes INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (code)
);
CREATE TABLE shipment_disruptions (
	shipment_id VARCHAR NOT NULL, 
	disruption_id VARCHAR NOT NULL, 
	PRIMARY KEY (shipment_id, disruption_id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(disruption_id) REFERENCES disruption_windows (id)
);
CREATE TABLE shipment_issues (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR, 
	tracking_event_id VARCHAR, 
	issue_type VARCHAR(60) NOT NULL, 
	ground_truth_label VARCHAR(60) NOT NULL, 
	details TEXT NOT NULL, 
	detected_at DATETIME NOT NULL, 
	resolved_at DATETIME, 
	is_resolved BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(tracking_event_id) REFERENCES tracking_events (id)
);
CREATE TABLE shipment_legs (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR NOT NULL, 
	route_id VARCHAR NOT NULL, 
	carrier_id VARCHAR, 
	leg_number INTEGER NOT NULL, 
	origin_facility_id VARCHAR NOT NULL, 
	destination_facility_id VARCHAR NOT NULL, 
	planned_departure_at DATETIME NOT NULL, 
	planned_arrival_at DATETIME NOT NULL, 
	actual_departure_at DATETIME, 
	actual_arrival_at DATETIME, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (shipment_id, leg_number), 
	CHECK (leg_number > 0), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(route_id) REFERENCES routes (id), 
	FOREIGN KEY(carrier_id) REFERENCES carriers (id), 
	FOREIGN KEY(origin_facility_id) REFERENCES facilities (id), 
	FOREIGN KEY(destination_facility_id) REFERENCES facilities (id)
);
CREATE TABLE shipment_state_history (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR NOT NULL, 
	previous_status VARCHAR(30), 
	new_status VARCHAR(30) NOT NULL, 
	changed_at DATETIME NOT NULL, 
	source_event_id VARCHAR, 
	change_reason TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(source_event_id) REFERENCES tracking_events (id)
);
CREATE TABLE shipments (
	id VARCHAR NOT NULL, 
	carrier_id VARCHAR NOT NULL, 
	service_level_id VARCHAR NOT NULL, 
	origin_facility_id VARCHAR NOT NULL, 
	destination_facility_id VARCHAR NOT NULL, 
	created_at DATETIME NOT NULL, 
	planned_pickup_at DATETIME NOT NULL, 
	sla_deadline_at DATETIME NOT NULL, 
	actual_delivered_at DATETIME, 
	status VARCHAR(30) NOT NULL, 
	PRIMARY KEY (id), 
	CHECK (status IN ('CREATED', 'PICKED_UP', 'IN_TRANSIT', 'AT_FACILITY', 'OUT_FOR_DELIVERY', 'DELIVERED', 'CANCELLED', 'EXCEPTION')), 
	FOREIGN KEY(carrier_id) REFERENCES carriers (id), 
	FOREIGN KEY(service_level_id) REFERENCES service_levels (id), 
	FOREIGN KEY(origin_facility_id) REFERENCES facilities (id), 
	FOREIGN KEY(destination_facility_id) REFERENCES facilities (id)
);
CREATE TABLE tracking_events (
	id VARCHAR NOT NULL, 
	shipment_id VARCHAR NOT NULL, 
	leg_id VARCHAR, 
	facility_id VARCHAR, 
	event_code VARCHAR(50) NOT NULL, 
	event_time DATETIME NOT NULL, 
	ingestion_time DATETIME NOT NULL, 
	source_event_key VARCHAR(120), 
	source VARCHAR(50), 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id), 
	FOREIGN KEY(leg_id) REFERENCES shipment_legs (id), 
	FOREIGN KEY(facility_id) REFERENCES facilities (id)
);
CREATE TABLE weather_events (
	id VARCHAR NOT NULL, 
	event_type VARCHAR(50) NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME NOT NULL, 
	latitude FLOAT, 
	longitude FLOAT, 
	impact_description TEXT, 
	PRIMARY KEY (id), 
	CHECK (end_time > start_time)
);
CREATE INDEX idx_shipment_status ON shipments (status);
CREATE INDEX idx_shipment_sla ON shipments (sla_deadline_at);
CREATE INDEX idx_tracking_shipment_time ON tracking_events (shipment_id, event_time);
COMMIT;
